[CmdletBinding()]param([string]$ProjectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path,[string]$ReportPath='ES/Output/StaticReplay/es-abcd-framework-parity.json')
$ErrorActionPreference='Stop';$root=(Resolve-Path -LiteralPath $ProjectRoot).Path;Import-Module (Join-Path $root 'ES/Automation/ABCD/ESABCDFrameworkParity.psm1') -Force
$m=Get-ESABCDFrameworkCoverage;$cases=@();foreach($f in @($m.frameworks)){foreach($cap in @($f.capabilities)){$payload=[ordered]@{probe='parity';framework=$f.frameworkId;scope='project';feedback='observed';reflection='bounded-reflection';count=2;max=3;used=0;output='';text='{}';maxLines=20;pruned=@('b1');backtrack=$true;seed='fixed';turns=3;stale=$false;score=0.7;expected='same';actual='same';trace=@('a','b');toolCalls=@('read')};try{$r=Invoke-ESABCDFrameworkCapability -FrameworkId $f.frameworkId -CapabilityId $cap -Payload $payload;$ok=($r.status -eq 'adapted' -and $null -ne $r.result)}catch{$ok=$false};$cases+=,[pscustomobject]@{frameworkId=$f.frameworkId;framework=$f.frameworkId;capability=$cap;status=if($ok){'adapted'}else{'failed'}}}}
$negativeCases=@(
 [pscustomobject]@{frameworkId='swe-agent-aci';capability='bounded-tool-surface';payload=[ordered]@{scope=$null};expected='reject'},
 [pscustomobject]@{frameworkId='swe-agent-aci';capability='edit-lint-gate';payload=[ordered]@{text='{';scope='project'};expected='reject'},
 [pscustomobject]@{frameworkId='reflexion';capability='feedback-capture';payload=[ordered]@{feedback=$null};expected='reject'},
